export async function listWalkFiles(
  workspaceRoot: string,
  getAttempt?: (filePath: string, ref: string) => AttemptSummary | undefined,
  getProgress?: (filePath: string, ref: string) => WalkProgressSummary | undefined,
): Promise<WalkFileSummary[]> {
  const filePaths = await findCodewalkFiles(workspaceRoot);
  // 並行讀取:Promise.all 保證回傳順序等同 filePaths,與檔案讀完的先後無關
  return Promise.all(
    filePaths.map(async (filePath) => {
      const result = await loadCodewalkFile(filePath);
      const summary: WalkFileSummary = {
        path: filePath,
        title: result.valid ? result.value.title : basename(filePath),
      };
      if (result.valid && getAttempt) {
        const lastAttempt = getAttempt(filePath, result.value.ref);
        if (lastAttempt) {
          summary.lastAttempt = lastAttempt;
        }
      }
      if (result.valid && getProgress) {
        const progress = getProgress(filePath, result.value.ref);
        if (progress) {
          summary.progress = progress;
        }
      }
      return summary;
    }),
  );
}

export function activate(context: vscode.ExtensionContext): void {
  // 必須早於 WalkPlayerViewProvider 的建構——getHtml() 會用到判定結果
  // (design.md 決策 5)。
  setLocale(resolveLocale(vscode.env.language));
  const provider = new WalkPlayerViewProvider(context);

  context.subscriptions.push(
    // retainContextWhenHidden:面板隱藏(切到其他側邊面板)時不重建 webview,
    // 讀者切走再切回來能維持原本讀到哪、捲動位置與展開中的術語(reading-progress
    // capability「面板重建後還原閱讀位置」,design.md 決策 1 第 1 層)。
    vscode.window.registerWebviewViewProvider(WalkPlayerViewProvider.viewId, provider, {
      webviewOptions: { retainContextWhenHidden: true },
    }),
    vscode.commands.registerCommand('codewalk.openWalk', () => {
      void vscode.commands.executeCommand(`${WalkPlayerViewProvider.viewId}.focus`);
    }),
    vscode.commands.registerCommand('codewalk.nextStep', () => provider.handleNextStep()),
    vscode.commands.registerCommand('codewalk.prevStep', () => provider.handlePrevStep()),
    vscode.commands.registerCommand('codewalk.revealCurrentStep', () => provider.handleRevealCurrentStep()),
    vscode.window.registerUriHandler(createUriHandler(provider)),
  );

  private getHtml(webview: vscode.Webview): string {
    const scriptUri = webview.asWebviewUri(
      vscode.Uri.joinPath(this.context.extensionUri, 'dist', 'webview.js'),
    );
    const styleUri = webview.asWebviewUri(
      vscode.Uri.joinPath(this.context.extensionUri, 'dist', 'webview.css'),
    );
    const codiconUri = webview.asWebviewUri(
      vscode.Uri.joinPath(this.context.extensionUri, 'dist', 'codicon.css'),
    );
    const nonce = Array.from({ length: 32 }, () => Math.floor(Math.random() * 16).toString(16)).join('');
    // getLocale() 讀的是 activate() 首行已設定好的 host locale——webview 開機時
    // 從這個標籤讀回判定結果,兩邊共用同一個 resolveLocale()(design.md 決策 4、5)。
    const htmlLang = getLocale() === 'zh-tw' ? 'zh-Hant' : 'en';

    return `<!DOCTYPE html>
<html lang="${htmlLang}">
<head>
  <meta charset="UTF-8" />
  <meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src ${webview.cspSource}; font-src ${webview.cspSource}; script-src 'nonce-${nonce}';" />
  <!-- codicon.css 要先載入:它對 .codicon 的 font-size 用 font 這個 shorthand 屬性設定,
       跟 theme.css 裡對應覆寫的 selector specificity 打平時,cascade 順序在後的會贏,
       所以 theme.css 必須排在 codicon.css 之後,尺寸覆寫才會生效。 -->
  <link href="${codiconUri}" rel="stylesheet" />
  <link href="${styleUri}" rel="stylesheet" />
</head>
<body>
  <div id="app" tabindex="0"></div>
  <script nonce="${nonce}" src="${scriptUri}"></script>
</body>
</html>`;
  }

items.anchor:
export type WebviewToHostMessage =
  /** webview 腳本啟動完成。host 回以主題、導讀列表,必要時回灌目前導讀。 */
  | { type: 'webviewReady' }
  /** 從列表選定一份導讀,從第一步開始。 */
  | { type: 'selectWalkFile'; path: string }
  | { type: 'nextStep' }
  | { type: 'prevStep' }
  /** 直接跳到指定步驟。也用於重播當前步驟的跳轉(取消 quiz、重走導讀、開啟失準檔案)。 */
  | { type: 'jumpToStep'; stepIndex: number }
  /** 送出 quiz 答案。未作答的題目以 -1 表示(見 shared/schema.ts 的 scoreQuiz)。 */
  | { type: 'quizSubmitted'; answers: number[] }
  /** 開啟外部連結。host 交給 VS Code 處理,webview 本身無法開啟瀏覽器。 */
  | { type: 'openReference'; url: string }
  /** 點擊 snippet 或 diff 的標題列,跳到它指向的位置。 */
  | { type: 'jumpToSnippet'; stepIndex: number; itemIndex: number }
  /** 清除某份導讀的 Quiz 作答紀錄。 */
  | { type: 'clearAttempt'; path: string }
  /** 把導讀的 regenerateHint 複製到剪貼簿。 */
  | { type: 'copyRegenerateHint' }
  /**
   * 把目前步驟(可選地帶框選文字)交給 AI 助手。`selection` 省略代表問整步,
   * 不另立布林欄位——意圖本來就是同一個,差別只在送到哪(design.md 決策 7)。
   */
  | { type: 'askAgent'; destination: AskAgentDestination; selection?: string }
  /** 從列表接續上次的閱讀進度;與 selectWalkFile 的差別是起始步驟與不跳轉編輯器。 */
  | { type: 'resumeWalk'; path: string }
  /** 把編輯器帶回目前步驟的位置(面板按鈕或 Home 鍵)。 */
  | { type: 'revealCurrentStep' }
  /**
   * 從走讀/quiz 結果畫面返回列表——與 webviewReady 分開,因為 host 用
   * currentWalk 是否存在判斷「該不該回灌 walkRestored」(design.md 決策 1);
   * 若沿用 webviewReady 讓 host 誤以為仍在同一份導讀,回列表會被立刻拉回去。
   */
  | { type: 'backToList' };

