private async handleMessage(raw: unknown): Promise<void> {
  const msg = parseWebviewToHostMessage(raw);
  if (!msg) return;

  switch (msg.type) {
    case 'webviewReady':
      await this.sendTheme();
      if (this.pendingOpenRequest) {
        const { path, stepIndex } = this.pendingOpenRequest;
        this.pendingOpenRequest = undefined;
        await this.loadWalk(path);
        if (stepIndex !== undefined) await this.setStep(stepIndex);
      } else if (this.pendingOpenError) {
        const message = this.pendingOpenError;
        this.pendingOpenError = undefined;
        this.post({ type: 'loadError', message });
      } else {
        await this.sendFileList();
        await this.sendRestoreIfActive();
      }
      break;
    case 'selectWalkFile':
      await this.loadWalk(msg.path);
      break;
    case 'resumeWalk':
      await this.loadWalk(msg.path, { resume: true });
      break;
    case 'revealCurrentStep':
      await this.jumpToCurrentStep();
      break;
    case 'nextStep':
      await this.moveStep(1);
      break;
    case 'prevStep':
      await this.moveStep(-1);
      break;
    case 'jumpToStep':
      await this.setStep(msg.stepIndex);
      break;
    case 'quizSubmitted':
      await this.handleQuizSubmitted(msg.answers);
      break;
    case 'openReference':
      await vscode.env.openExternal(vscode.Uri.parse(msg.url));
      break;
    case 'jumpToSnippet':
      await this.handleJumpToSnippet(msg.stepIndex, msg.itemIndex);
      break;
    case 'clearAttempt':
      await this.handleClearAttempt(msg.path);
      break;
    case 'copyRegenerateHint':
      await this.handleCopyRegenerateHint();
      break;
    case 'askAgent':
      await this.handleAskAgent(msg.destination, msg.selection);
      break;
    case 'backToList':
      this.clearActiveWalk();
      await this.sendFileList();
      break;
  }
}

