private async loadWalk(path: string, options: { resume?: boolean } = {}): Promise<void> {
  let result: Awaited<ReturnType<typeof loadCodewalkFile>>;
  try {
    result = await loadCodewalkFile(path);
  } catch {
    // 檔案不存在或無法讀取時 loadCodewalkFile() 直接拋出(walkLoader.ts 的
    // @throws 說明)——只有 JSON 格式錯誤才會走 { valid: false } 的優雅路徑。
    // URI handler 帶進來的路徑是外部程序給的字串,指向不存在的檔案是完全
    // 合理會發生的情況,不能讓它變成沒人接的 rejection(ask-agent capability
    // 「不可用時明確告知」的同一個精神)。
    this.post({ type: 'loadError', message: t('host.fileNotFound', { file: path }) });
    return;
  }
  if (!result.valid) {
    this.post({ type: 'loadError', message: result.errors.join('; ') });
    return;
  }

  this.currentWalk = result.value;
  this.currentWalkPath = path;
  this.refDrifted = false;

  const root = getWorkspaceRoot();
  if (root) {
    const head = await getWorkspaceHead(root);
    this.refDrifted = head !== null && isRefDrifted(head, result.value.ref);
    this.anchorReport = buildAnchorReport(root, result.value);
  } else {
    this.anchorReport = emptyAnchorReport(result.value);
  }

  const maxIndex = this.currentWalk.steps.length - 1;
  const progress =
    options.resume && root ? this.progressStore.get(root, path, result.value.ref) : undefined;
  this.stepIndex = Math.min(Math.max(progress?.stepIndex ?? 0, 0), maxIndex);

  this.post({
    type: 'walkLoaded',
    walk: this.currentWalk,
    stepIndex: this.stepIndex,
    refDrifted: this.refDrifted,
    anchorReport: this.anchorReport,
    snippetPreviews: await this.readCurrentSnippetPreviews(),
  });
  if (!options.resume) {
    await this.jumpToCurrentStep();
  }
}

export function isRefDrifted(headSha: string, ref: string): boolean {
  return headSha.trim() !== ref.trim();
}

/**
 * 取得 workspace 目前的 HEAD commit SHA。
 *
 * @returns 非 git 專案、git 不可用、或指令失敗時回傳 null——此時單純不做漂移
 * 偵測,不影響導讀播放
 */
export async function getWorkspaceHead(workspaceRoot: string): Promise<string | null> {
  try {
    const { stdout } = await exec('git rev-parse HEAD', { cwd: workspaceRoot });
    return stdout.trim();
  } catch {
    return null;
  }
}

