/**
 * 對 `askAgent` 的結果回報。**送進 chat 失敗而退回剪貼簿時,webview 不能
 * 樂觀地顯示「已送出」**——那是靜默且誤導的失敗(design.md 決策 6),
 * 所以這則訊息一律等 host 端動作完成才送出,不是意圖的鏡射。
 */
| { type: 'askAgentResult'; outcome: AskAgentOutcome };

/**
 * 把目前步驟(可選地帶框選文字)交給 AI 助手。`selection` 省略代表問整步,
 * 不另立布林欄位——意圖本來就是同一個,差別只在送到哪(design.md 決策 7)。
 */
| { type: 'askAgent'; destination: AskAgentDestination; selection?: string }

steps.anchor:
/**
 * 讀者觸發「把這一步交給 AI」時選擇的出口。兩者產生完全相同的提問內容,
 * 差別只在送到哪(ask-agent capability「把當前步驟交給 AI 助手的入口」)。
 */
export type AskAgentDestination = 'chat' | 'clipboard';

/**
 * `askAgent` 訊息實際發生的結果,決定 webview 該顯示什麼回饋。`chatUnavailable`
 * 與 `failed` 是兩種不同的降級:前者已改寫剪貼簿成功,後者連剪貼簿都失敗
 * (design.md 決策 6)。
 */
export type AskAgentOutcome = 'chat' | 'clipboard' | 'chatUnavailable' | 'failed';

/**
 * 組出交給 AI 助手的提問內容。
 *
 * @param walkPath - 導讀檔的絕對路徑
 * @param workspaceRoot - workspace 根目錄;沒有已開啟的 workspace 時為 `undefined`
 * @param stepStatus - 目前步驟的錨驗證結果,決定行號換算與是否附加失準警示
 * @param selection - 讀者框選的文字;未框選時省略,提問以整步為對象
 *
 * @remarks
 * 刻意不含 `narration` 全文——實測本 repo 兩份導讀 narration 中位數落在
 * 545~1305 字元,全帶會讓 chat 輸入框需要捲動才看得完(design.md 決策 1)。
 * 提問改帶指標(導讀檔路徑 + 步驟索引),讓 agent 自己讀進去,拿到的比塞給它
 * 的更多。
 */
export function buildAskAgentPrompt(input: {
  walk: CodewalkFile;
  walkPath: string;
  workspaceRoot: string | undefined;
  stepIndex: number;
  stepStatus: AnchorStatus;
  selection?: string;
}): string {
  const step = input.walk.steps[input.stepIndex];
  const location = toWorkspaceRelativePath(input.workspaceRoot, input.walkPath);
  const { startLine, endLine } = effectiveLineRange(step, input.stepStatus);

  const lines = [
    t('askAgent.promptIntro', { step: input.stepIndex + 1, title: step.title }),
    t('askAgent.promptLocation', { path: location, index: input.stepIndex }),
    t('askAgent.promptFileRef', { file: step.file, startLine, endLine }),
  ];

  if (input.stepStatus.kind === 'stale') {
    lines.push(t('askAgent.promptStale'));
  }

  if (input.selection !== undefined) {
    lines.push('', t('askAgent.promptSelectionLabel'), input.selection);
  }

  lines.push('', t('askAgent.promptInstruction', { index: input.stepIndex }));

  return lines.join('\n');
}

private async handleAskAgent(destination: AskAgentDestination, selection?: string): Promise<void> {
  if (!this.currentWalk || !this.currentWalkPath) return;
  const status = this.anchorReport?.steps[this.stepIndex]?.step ?? { kind: 'unanchored' as const };
  const prompt = buildAskAgentPrompt({
    walk: this.currentWalk,
    walkPath: this.currentWalkPath,
    workspaceRoot: getWorkspaceRoot(),
    stepIndex: this.stepIndex,
    stepStatus: status,
    selection,
  });

  if (destination === 'clipboard') {
    await this.writeAskAgentClipboard(prompt, 'clipboard');
    return;
  }

  try {
    // isPartialQuery: true——只填入不代讀者送出。Cursor 本來就不自動送
    // (即使支援此命令的版本也只填入),設 true 讓兩個編輯器行為一致
    // (design.md 決策 4)。不預先用 getCommands() 偵測命令是否存在:
    // 那只答得出「存不存在」,答不出「執行失敗」,try/catch 兩者都涵蓋
    // (design.md 決策 5)。
    await vscode.commands.executeCommand('workbench.action.chat.open', {
      query: prompt,
      isPartialQuery: true,
    });
    if (!this.chatWarmedUp) {
      this.chatWarmedUp = true;
      // 冷啟動時 Chat 自己的 webview 常常還沒掛載完成,query 就被吃掉了
      // (讀者要點兩次才生效,見手動驗證的實測結果)。只在這個 session 的
      // 第一次補送一次;之後面板已經「熱」了,不再需要這個延遲。冷啟動
      // 當下面板連可互動的輸入框都還沒掛出來,不會有「補送蓋掉讀者已輸入
      // 內容」的風險。
      await new Promise((resolve) => setTimeout(resolve, 400));
      await vscode.commands.executeCommand('workbench.action.chat.open', {
        query: prompt,
        isPartialQuery: true,
      });
    }
    this.post({ type: 'askAgentResult', outcome: 'chat' });
  } catch {
    await this.writeAskAgentClipboard(prompt, 'chatUnavailable');
  }
}

