function createMcpServer(provider: WalkPlayerViewProvider, workspaceRoot: string): McpServer {
  const server = new McpServer({ name: 'codewalk-reader', version: '1.0.0' });

  server.registerTool(
    'codewalk_current_step',
    {
      title: 'CodeWalk current step',
      description: '取得讀者目前在 CodeWalk 面板瀏覽到哪一份導讀、第幾步(唯讀,不改變面板狀態)。',
    },
    async () => {
      const snapshot = provider.getCurrentStepSnapshot();
      return { content: [{ type: 'text', text: JSON.stringify(snapshot) }] };
    },
  );

  server.registerTool(
    'codewalk_list_walks',
    {
      title: 'CodeWalk list walks',
      description: '列出目前 workspace 下可播放的導讀(路徑與標題)。',
    },
    async () => {
      const files = await listWalkFiles(workspaceRoot);
      const result = buildAgentWalkList(files, workspaceRoot);
      return { content: [{ type: 'text', text: JSON.stringify(result) }] };
    },
  );

  return server;
}

/**
 * 算出某個 workspace 對應的探索檔絕對路徑。同一個 `workspaceRoot` 一律得到
 * 同一個路徑,不同 workspace 天生不會撞到同一份檔案。
 *
 * @param tmpDir - `os.tmpdir()` 的回傳值,呼叫端傳入以便測試不依賴實際檔案系統
 */
export function computeDiscoveryFilePath(tmpDir: string, workspaceRoot: string): string {
  const hash = createHash('sha256').update(workspaceRoot).digest('hex').slice(0, 16);
  return join(tmpDir, 'codewalk-mcp', `${hash}.json`);
}

steps.anchor:
/**
 * 啟動 MCP server。呼叫端(`extension.ts`)必須以 fire-and-forget 呼叫,啟動
 * 失敗不該擋住 extension 的其他功能(design.md 決策 9)。
 *
 * @remarks
 * 先對探索檔記錄的 port(若存在)做一次 health check——活著就判定另一個視窗
 * 已在服務這個 workspace,不啟動也不覆蓋,只通知讀者一次;沒反應則視為殭屍
 * 記錄或首次啟動,正常覆蓋(design.md 決策 4)。
 */
export async function startMcpServer(provider: WalkPlayerViewProvider, workspaceRoot: string): Promise<void> {
  const discoveryFilePath = computeDiscoveryFilePath(tmpdir(), workspaceRoot);
  const existing = await readDiscoveryInfo(discoveryFilePath);
  if (existing && (await isServerAlive(existing.port))) {
    vscode.window.showInformationMessage(t('mcp.anotherWindowServing'));
    return;
  }

  const mcpServer = createMcpServer(provider, workspaceRoot);
  const transport = new StreamableHTTPServerTransport({ sessionIdGenerator: () => randomUUID() });
  await mcpServer.connect(transport);

  const server = createServer((req, res) => {
    if (req.method === 'GET' && req.url === '/health') {
      res.writeHead(200).end('ok');
      return;
    }
    void transport.handleRequest(req, res);
  });

  await new Promise<void>((resolve, reject) => {
    server.once('error', reject);
    server.listen(0, '127.0.0.1', resolve);
  });

  const address = server.address();
  const port = typeof address === 'object' && address ? address.port : 0;

  await mkdir(dirname(discoveryFilePath), { recursive: true });
  const info: McpDiscoveryInfo = { port, pid: process.pid };
  await writeFile(discoveryFilePath, JSON.stringify(info));

  httpServer = server;
  ownDiscoveryFilePath = discoveryFilePath;
}

items.anchor:
/** `codewalk_current_step` 的回傳形狀。沒有作用中導讀時是合法狀態,不是錯誤(design.md 決策 5)。 */
export type CurrentStepSnapshot =
  | { active: false }
  | {
      active: true;
      walkPath: string;
      walkTitle: string;
      stepIndex: number;
      stepTitle: string;
      file: string;
      startLine: number;
      endLine: number;
      anchorStatus: AnchorStatus['kind'];
    };

export function buildAgentWalkList(
  files: WalkFileSummary[],
  workspaceRoot: string | undefined,
): AgentWalkListResult {
  return {
    walks: files.map((file) => ({
      path: toWorkspaceRelativePath(workspaceRoot, file.path),
      title: file.title,
    })),
  };
}

steps.anchor:
/**
 * 組出 `codewalk_current_step` 的回傳內容。
 *
 * @param walk - 目前作用中的導讀;沒有作用中導讀時為 `undefined`
 * @param walkPath - 導讀檔的絕對路徑;與 `walk` 同時存在或同時缺席
 * @param stepStatus - 目前步驟的錨驗證結果,決定行號換算與回報的狀態
 *
 * @remarks
 * 行號一律走既有 `effectiveLineRange()`,路徑一律走既有 `toWorkspaceRelativePath()`
 * ——與面板顯示、`askAgentPrompt.ts` 用同一套邏輯,不重算(design.md 決策 5)。
 * 失準的步驟如實回報 `anchorStatus: 'stale'`,不隱藏(ask-agent capability
 * 「失準的步驟必須在提問中標明」的同一個精神,套用到查詢介面)。
 */
export function buildCurrentStepSnapshot(input: {
  walk: CodewalkFile | undefined;
  walkPath: string | undefined;
  workspaceRoot: string | undefined;
  stepIndex: number;
  stepStatus: AnchorStatus;
}): CurrentStepSnapshot {
  if (!input.walk || !input.walkPath) return { active: false };
  const step = input.walk.steps[input.stepIndex];
  const { startLine, endLine } = effectiveLineRange(step, input.stepStatus);

  return {
    active: true,
    walkPath: toWorkspaceRelativePath(input.workspaceRoot, input.walkPath),
    walkTitle: input.walk.title,
    stepIndex: input.stepIndex,
    stepTitle: step.title,
    file: step.file,
    startLine,
    endLine,
    anchorStatus: input.stepStatus.kind,
  };
}
